using System;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Threading.Tasks;
using Avalonia.Threading;
using AmplitudeSoundboard;

namespace Amplitude.Helpers;

// Profile reads and requests are serialized on the UI thread; native output
// initialization runs on a worker so a driver stall cannot block the window.
// No audio is generated by a health check, and OBS/Zoom are never restarted.
internal sealed class SoundboardRecovery : IDisposable
{
    private readonly MSoundEngine engine;
    private readonly OutputProfileManager profiles;
    private readonly DispatcherTimer timer;
    private readonly string folder;
    private readonly RecoverySchedule schedule = new();
    private string request = "";
    private string lastStatus = "";
    private bool repairing;

    internal SoundboardRecovery(MSoundEngine engine, OutputProfileManager profiles)
    {
        this.engine = engine;
        this.profiles = profiles;
        folder = App.APP_STORAGE;
        timer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
        timer.Tick += Tick;
        timer.Start();
    }

    private async void Tick(object? sender, EventArgs args)
    {
        if (repairing || MacSession.IsLocked()) return;
        repairing = true;
        try
        {
            string path = Path.Join(folder, "repair-request.txt");
            string incoming = File.Exists(path) ? File.ReadAllText(path).Trim() : "";
            bool requested = incoming.Length > 0 && incoming != request;
            if (requested) request = incoming;
            bool idle = !engine.CurrentlyPlaying.Any() && !engine.Queued.Any();
            string devices = await Task.Run(engine.DeviceSnapshot);
            if (!schedule.Poll(DateTimeOffset.UtcNow, devices, requested, idle)) return;

            var names = profiles.OutputProfilesList.SelectMany(p => p.OutputSettings).Select(s => s.DeviceName).Distinct().ToArray();
            bool ready = await Task.Run(() => engine.RecoverOutputs(names));
            schedule.Complete(ready);
            string status = ready ? "ready" : "waiting-for-audio-device";
            if (status != lastStatus || requested)
            {
                string log = Path.Join(folder, "audio-recovery.log");
                if (File.Exists(log) && new FileInfo(log).Length > 65536) File.Move(log, log + ".old", true);
                File.AppendAllText(log, $"{DateTimeOffset.Now:O} {status}: {string.Join(", ", names)}\n");
                lastStatus = status;
            }
            // A nonce ties the acknowledgement to this specific key press.
            string temporary = Path.Join(folder, "repair-status.txt.tmp");
            File.WriteAllLines(temporary, new[] { request, status, Environment.ProcessId.ToString(), DateTimeOffset.Now.ToString("O") });
            File.Move(temporary, Path.Join(folder, "repair-status.txt"), true);
        }
        catch (IOException) { /* Atomic launcher writes may be retried next tick. */ }
        catch (UnauthorizedAccessException) { }
        finally { repairing = false; }
    }

    public void Dispose()
    {
        timer.Stop();
        timer.Tick -= Tick;
    }
}

internal static class MacSession
{
    private const string CoreFoundation = "/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation";
    [DllImport("/System/Library/Frameworks/CoreGraphics.framework/CoreGraphics")]
    private static extern IntPtr CGSessionCopyCurrentDictionary();
    [DllImport(CoreFoundation)]
    private static extern IntPtr CFStringCreateWithCString(IntPtr allocator, string value, uint encoding);
    [DllImport(CoreFoundation)]
    private static extern IntPtr CFDictionaryGetValue(IntPtr dictionary, IntPtr key);
    [DllImport(CoreFoundation)]
    private static extern byte CFBooleanGetValue(IntPtr value);
    [DllImport(CoreFoundation)]
    private static extern void CFRelease(IntPtr value);

    internal static bool IsLocked()
    {
        if (!OperatingSystem.IsMacOS()) return false;
        var dictionary = CGSessionCopyCurrentDictionary();
        if (dictionary == IntPtr.Zero) return true;
        var key = CFStringCreateWithCString(IntPtr.Zero, "CGSSessionScreenIsLocked", 0x08000100);
        try
        {
            var value = CFDictionaryGetValue(dictionary, key);
            return value != IntPtr.Zero && CFBooleanGetValue(value) != 0;
        }
        finally
        {
            if (key != IntPtr.Zero) CFRelease(key);
            CFRelease(dictionary);
        }
    }
}

// Kept independent of native audio so reconnect ordering can be exercised.
internal sealed class RecoverySchedule
{
    private DateTimeOffset lastPoll;
    private string? snapshot;
    private bool pending;
    private int stableTicks;

    internal bool Poll(DateTimeOffset now, string devices, bool requested, bool idle)
    {
        bool changed = devices != snapshot;
        bool resumed = lastPoll != default && now - lastPoll > TimeSpan.FromSeconds(10);
        lastPoll = now;
        if (changed || resumed || requested)
        {
            snapshot = devices;
            pending = true;
            stableTicks = 0;
        }
        else stableTicks++;
        // Let Bluetooth settle, and let a playing clip finish before repair.
        return pending && stableTicks >= 1 && idle;
    }

    internal void Complete(bool ready) => pending = !ready;
}
